import { useState, useEffect } from 'react';
import { getTasks } from '../../api';
import type { Task } from '../../types';
import './TaskBoard.css';

const SKELETON_COUNT = 3;

function renderListItems(tasks: Task[] | null): React.ReactNode {
  if (tasks === null) {
    return Array.from({ length: SKELETON_COUNT }, (_, i) => (
      <li key={i} className="task-item task-item--skeleton">
        <span className="task-item-title skeleton-line" />
      </li>
    ));
  }

  if (tasks.length === 0) {
    return (
      <li className="task-item">
        <p className="task-board-empty-message">No tasks found.</p>
      </li>
    );
  }

  return tasks.map((task) => (
    <li key={task.id} className="task-item">
      <span className="task-item-title">{task.title}</span>
    </li>
  ));
}

export function TaskBoard(): React.ReactElement {
  const [tasks, setTasks] = useState<Task[] | null>(null);

  useEffect(() => {
    getTasks()
      .then((fetched) => setTasks(fetched))
      .catch(() => setTasks([]));
  }, []);

  const isLoading = tasks === null;
  const count = isLoading ? 0 : tasks.length;

  return (
    <div className="task-board">
      <header className="task-board-header">
        <h2 className="task-board-heading">Tasks</h2>
        <span className="task-board-badge" aria-live="polite" aria-label={`${count} tasks`}>
          {count}
        </span>
      </header>
      <div className="task-board-filter-bar" role="search" aria-label="Filter tasks" />
      <ul className="task-board-list" aria-label="Task list">
        {renderListItems(tasks)}
      </ul>
    </div>
  );
}
